mapper.select:
SELECT IF(u.`user_id` IS NULL,"用户已注销",u.`user_name`) AS userName, u.`avatar`, IF(s.`shop_id` IS NULL,"酒店已下架",s.shop_name) AS shopName, s.`title_img` AS titleImg, e.* FROM
sys_evaluate e LEFT JOIN tb_user u ON e.`user_id` = u.`user_id` left join shops s on e.shop_id = s.shop_id WHERE is_delete = 0
and e.user_id = #{evaluate.userId}
and e.shop_id = #{evaluate.shopId}
and e.satisfaction_flag = #{evaluate.satisfactionFlag}
and e.order_number like concat("%",#{evaluate.orderNumber},"%")
and u.userName like concat("%",#{evaluate.userName},"%")
and e.shop_name like concat("%",#{evaluate.shopName},"%")
order by e.create_time desc
